/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by tools/sympy-corpus/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { Add, Dummy, Lambda, Matrix, Pow, dummyEq, fn, parseMathematica, rational, symbols } from '../../src';
import { sympyStr } from '../sympy-str';

describe("doctests of sympy.parsing.mathematica", () => {
  it("parse_mathematica(\"Sin[x]^2 Tan[y]\")", () => {
    expect(sympyStr(parseMathematica('Sin[x]^2 Tan[y]'))).toBe('sin(x)**2*tan(y)');
  });
  // no value
  //   e.replace(Function("F"), lambda *x: Max(*x)*Min(*x))
  //   => 21
  it.todo("e.replace(Function(\"F\"), lambda *x: Max(*x)*Min(*x))");
  it("parse_mathematica(\"x*(a + b)\")", () => {
    expect(sympyStr(parseMathematica('x*(a + b)'))).toBe('x*(a + b)');
  });
  it("parse_mathematica(\"Times[x, Plus[a, b]]\")", () => {
    expect(sympyStr(parseMathematica('Times[x, Plus[a, b]]'))).toBe('x*(a + b)');
  });
  it("Matrix(m)", () => {
    const [a, b, c, d] = symbols('a b c d');
    expect(sympyStr(Matrix.of([[a, b], [c, d]]))).toBe('Matrix([[a, b], [c, d]])');
  });
  it("parse_mathematica(\"x_.\")", () => {
    expect(sympyStr(parseMathematica('x_.'))).toBe('Optional(Pattern(x, Blank()))');
  });
  it("parse_mathematica(\"Plus @@ {x, y, z}\")", () => {
    expect(sympyStr(parseMathematica('Plus @@ {x, y, z}'))).toBe('Apply(Plus, (x, y, z))');
  });
  it("parse_mathematica(\"f[x_, 3] := x^3 /; x > 0\")", () => {
    expect(sympyStr(parseMathematica('f[x_, 3] := x^3 /; x > 0'))).toBe('SetDelayed(f(Pattern(x, Blank()), 3), Condition(x**3, x > 0))');
  });
  it("e", () => {
    expect(sympyStr(parseMathematica('F[7,5,3]'))).toBe('F(7, 5, 3)');
  });
  it("m", () => {
    expect(sympyStr(parseMathematica('{{a, b}, {c, d}}'))).toBe('((a, b), (c, d))');
  });
});

